-- Generated by scripts/places (athletic.net dumps). Inserts MeetPlacings (Place, 0 points, no participant) only where the performance has none. Id-independent; re-runnable.
SET QUOTED_IDENTIFIER ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @pid INT;

-- 2010 OHSAA Division I State Track and Field Championships: Jennifer Foster Pole Vault place 11
SET @pid = (SELECT TOP 1 p.Id FROM Performances p JOIN Athletes a ON a.Id=p.AthleteId JOIN Meets m ON m.Id=p.MeetId JOIN Events e ON e.Id=p.EventId WHERE a.FirstName+N' '+a.LastName=N'Jennifer Foster' AND a.Gender=2 AND m.Name=N'2010 OHSAA Division I State Track and Field Championships' AND CAST(m.Date AS date)='2010-06-04' AND e.Name=N'Pole Vault' AND e.Gender=2);
IF @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM MeetPlacings WHERE PerformanceId=@pid) INSERT INTO MeetPlacings (MeetId, PerformanceId, MeetParticipantId, Place, FullPoints, SplitPoints) SELECT MeetId, Id, NULL, 11, 0, 0 FROM Performances WHERE Id=@pid;
